#!/bin/bash
cd "/d/claude projects"
A="D:/claude projects/crypto-news-terminal/app"
g() { echo ">>> $1"; python glm_build.py --model glm --file "$A/$1" --task "$2" 2>&1 | tail -1; }

g ws-server.js 'Apply these fixes, change nothing else: (1) Construct the server bound to loopback only: new WebSocketServer({ host: "127.0.0.1", port: PORT }). (2) Inside the wss.on("connection", async (ws) => {...}) handler, as its FIRST statement add: ws.on("error", (e) => console.error("[ws] client error:", e.message)); so a protocol error from one client can never crash the process. (3) Add wss.on("error", (e) => { console.error("[ws] server error:", e.message); if (e.code === "EADDRINUSE") { console.error("[ws] port " + PORT + " already in use"); process.exit(1); } }); right after the WebSocketServer is created. (4) Delete the final unconditional console.log line that prints "WebSocket server listening on port" at the bottom of the file (the wss "listening" event handler already logs it).'

g ingest.js 'When upserting an instrument by ticker, use its real name from the INSTRUMENTS list in ./lib/instruments instead of the ticker: require INSTRUMENTS (const { INSTRUMENTS } = require("./lib/instruments"); merge into the existing require of that module if there is one), and set create: { ticker, name: (INSTRUMENTS.find((i) => i.ticker === ticker) || {}).name || ticker }. Change nothing else.'

g package.json 'Edit only the "scripts" object: (1) "dev" becomes "next dev -H 127.0.0.1 -p 4180" and "start" becomes "next start -H 127.0.0.1 -p 4180". (2) Add a script "redis": "wsl -d Ubuntu -u root -- sh -c \"redis-cli ping >/dev/null 2>&1 && exec sleep infinity || exec redis-server /etc/redis/redis.conf --daemonize no\"" (keeps Redis in the foreground so WSL stays alive; if Redis is already running it just keeps WSL alive). (3) "redis:start" becomes an alias: "npm run redis". (4) "all" becomes: "concurrently -k -n redis,next,ws,ingest -c red,cyan,magenta,yellow \"npm:redis\" \"npm:dev\" \"npm:ws\" \"npm:ingest\"". Keep every other script and all dependencies exactly as they are. Output valid JSON.'

g README.md 'Update the setup instructions: (1) Add a Prerequisites section: Node 20+, PostgreSQL (any recent version, running on localhost:5432 with a database and user created for the app), Redis inside WSL Ubuntu installed with: wsl -d Ubuntu -u root -- sh -c "apt-get update && apt-get install -y redis-server". (2) Explain that Redis runs inside WSL, and WSL shuts down when idle, so Redis must run as a foreground process: `npm run all` now starts Redis (via `npm run redis`) together with Next.js, the WebSocket server and the ingest worker; for db:seed on its own, run `npm run redis` in a separate terminal first. (3) Replace any mention of "npm run redis:start" as a one-off service start with the above. (4) Note that the app binds to 127.0.0.1 only (http://localhost:4180, ws://localhost:4181). Keep all other existing content.'

g src/store/useFeedStore.ts 'Apply these fixes, change nothing else: (1) hydrate(posts): instead of replacing the list, when posts is non-empty: if the current source is "mock" start from an empty list, otherwise start from the current posts; then merge by id (incoming REST posts replace same-id entries, keep existing posts that are not in the incoming list, because live WebSocket posts may be newer than the REST query), cap at MAX_POSTS, and set source "live". (2) In upsertPost, when building the new flashIds object, also drop entries older than 5000 ms (Object.fromEntries(Object.entries(...).filter(([, t]) => Date.now() - t < 5000))) so flashIds never grows without bound.'

g src/hooks/useFeedSocket.ts 'Apply these fixes, change nothing else: (1) Add a function isPostDTO(x: unknown): x is PostDTO that checks x is a non-null object with string id, string title, string publishedAt, Array.isArray(instruments) and an object votes. Use it: for "snapshot" pass msg.posts.filter(isPostDTO); for "post"/"update" only call upsertPost if isPostDTO(msg.post). (2) In ws.onclose set status "closed" (not "connecting") before scheduling the reconnect; at the start of connect() (after the mounted check) set status "connecting".'

g src/app/api/prices/route.ts 'Only treat a CoinGecko response as good when it produced at least one price: update lastGood and write the Redis cache only if body.prices.length > 0; if the fetch succeeded but prices is empty, respond with the same fallback used in the error path (lastGood with stale: true, or the empty stale body). Change nothing else.'

g "src/app/api/posts/[id]/vote/route.ts" 'Remove the two `as any` casts in the voteData.upsert call. Import { Prisma } from "@prisma/client" and type the objects: const create: Prisma.VoteDataUncheckedCreateInput = { postId: id, [type]: 1 }; const update: Prisma.VoteDataUncheckedUpdateInput = { [type]: { increment: 1 } }; then pass create and update. Change nothing else.'

g src/components/FeedRow.tsx 'Performance fix, change nothing else: replace `const { flashIds, applyLocalVote, upsertPost } = useFeedStore();` with three selector calls: const flashAt = useFeedStore((s) => s.flashIds[post.id]); const applyLocalVote = useFeedStore((s) => s.applyLocalVote); const upsertPost = useFeedStore((s) => s.upsertPost); and compute isFlash as flash || (flashAt !== undefined && Date.now() - flashAt < 2500). Wrap the component in React memo: rename the function to FeedRowInner and add `export const FeedRow = memo(FeedRowInner);` with `import { memo, useState } from "react";`.'

g src/components/NewsFeed.tsx 'Performance fix, change nothing else: replace `const { posts, filter, portfolio } = useFeedStore();` with three selector calls: const posts = useFeedStore((s) => s.posts); const filter = useFeedStore((s) => s.filter); const portfolio = useFeedStore((s) => s.portfolio); and compute the visible list with useMemo keyed on [posts, filter, portfolio, now] (import useMemo from react if not already imported).'

g src/components/LeftSidebar.tsx 'Performance fix, change nothing else: replace `const { posts, filter, portfolio, setFilter, addTicker, removeTicker } = useFeedStore();` with six separate selector calls, one per field (e.g. const posts = useFeedStore((s) => s.posts);), and make sure the per-filter counts object is computed in a useMemo keyed on [posts, portfolio, now] (import useMemo from react if needed).'

g src/components/TrendingCoins.tsx 'Performance fix, change nothing else: replace `const { posts, addTicker } = useFeedStore();` with two selector calls: const posts = useFeedStore((s) => s.posts); const addTicker = useFeedStore((s) => s.addTicker); and ensure the trending computation is wrapped in useMemo keyed on [posts] (import useMemo from react if needed).'
echo ALL_FIXES_DONE
